-- igs-pharma#79: (C7) the owner's permissions are an explicit list in packages/rbac/src/catalogue.ts;
-- orders.create (a customer action) leaves the owner. (C2, D-034) new pharmacist-only permission
-- catalog.products.regulated.manage, granted to pharmacist, pharmacist_titular and system_seed.
-- The seed generator never infers removals, so the owner's one removal is written out (fix-forward).
DELETE FROM identity.role_permissions
WHERE role_key = 'owner' AND permission_key = 'orders.create';
